from __future__ import annotations

from collections import Counter, defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path
import shutil
from urllib.request import Request, urlopen
import zipfile

from PIL import Image

from .io import sha256_bytes, write_json, write_jsonl


BENCHMARK_VERSION = "KL-P4-1"
SELECTION_SEED = "kutarya-lens-phase4-v1"
TDIUC_URL = "https://kushalkafle.com/data/TDIUC.zip"
TDIUC_SHA256 = "76cc29febd7d8fe35aafb7ee2959a4307c27ccb2abab31f4667e820fde59d1b1"
TEXTVQA_URL = "https://dl.fbaipublicfiles.com/textvqa/data/TextVQA_0.5.1_val.json"
TEXTVQA_SHA256 = "4ceb5aadc1a41719d0a3e4dfdf06838bcfee1db569a9a65ee67d31c99893081d"
TDIUC_IMAGE_COUNT = 80
TEXTVQA_IMAGE_COUNT = 20

_TDIUC_CATEGORY = {
    "object_presence": "OBJECT",
    "object_recognition": "OBJECT",
    "counting": "COUNTING",
    "positional_reasoning": "SPATIAL",
    "activity_recognition": "ACTION",
    "sport_recognition": "ACTION",
    "scene_recognition": "SCENE",
    "color": "ATTRIBUTE",
    "attribute": "ATTRIBUTE",
}


@dataclass(frozen=True)
class ImageCandidate:
    image_id: str
    source_id: str
    source: str
    url: str
    questions: tuple[dict, ...]


def _rank(value: str) -> str:
    return hashlib.sha256(f"{SELECTION_SEED}:{value}".encode()).hexdigest()


def _download(url: str, destination: Path, expected_sha256: str | None = None) -> None:
    if destination.is_file():
        payload = destination.read_bytes()
        if expected_sha256 is None or sha256_bytes(payload) == expected_sha256:
            return
        raise ValueError(f"checksum mismatch for existing file: {destination}")
    destination.parent.mkdir(parents=True, exist_ok=True)
    request = Request(url, headers={"User-Agent": "Kutarya-Lens-Phase4/1.0"})
    with urlopen(request, timeout=120) as response, destination.open("wb") as handle:
        shutil.copyfileobj(response, handle)
    if expected_sha256 is not None and sha256_bytes(destination.read_bytes()) != expected_sha256:
        destination.unlink(missing_ok=True)
        raise ValueError(f"download checksum mismatch: {url}")


def _prepare_sources(cache_root: Path) -> tuple[Path, Path]:
    archive = cache_root / "TDIUC.zip"
    textvqa = cache_root / "TextVQA_0.5.1_val.json"
    _download(TDIUC_URL, archive, TDIUC_SHA256)
    _download(TEXTVQA_URL, textvqa, TEXTVQA_SHA256)
    extracted = cache_root / "tdiuc" / "TDIUC"
    members = {
        "TDIUC/Questions/OpenEnded_mscoco_val2014_questions.json",
        "TDIUC/Annotations/mscoco_val2014_annotations.json",
    }
    if not all((cache_root / "tdiuc" / item).is_file() for item in members):
        with zipfile.ZipFile(archive) as bundle:
            for member in members:
                bundle.extract(member, cache_root / "tdiuc")
    return extracted, textvqa


def _answers(annotation: dict) -> list[str]:
    values = [
        str(item["answer"] if isinstance(item, dict) else item).strip()
        for item in annotation["answers"]
    ]
    counts = Counter(values)
    accepted = sorted({value for value, count in counts.items() if count >= 3})
    if accepted:
        return accepted
    highest = max(counts.values())
    return sorted(value for value, count in counts.items() if count == highest)


def _tdiuc_candidates(root: Path) -> list[ImageCandidate]:
    questions_path = root / "Questions" / "OpenEnded_mscoco_val2014_questions.json"
    annotations_path = root / "Annotations" / "mscoco_val2014_annotations.json"
    questions = {
        item["question_id"]: item for item in json.loads(questions_path.read_text())["questions"]
    }
    grouped: dict[int, dict[str, list[dict]]] = defaultdict(lambda: defaultdict(list))
    annotations = json.loads(annotations_path.read_text())["annotations"]
    for annotation in annotations:
        image_id = annotation["image_id"]
        category = _TDIUC_CATEGORY.get(annotation["question_type"])
        if category is None or image_id >= 80_000_000:
            continue
        question = questions[annotation["question_id"]]
        grouped[image_id][category].append(
            {
                "source_question_id": str(annotation["question_id"]),
                "text": question["question"].strip(),
                "category": category,
                "accepted_answers": _answers(annotation),
                "source_question_type": annotation["question_type"],
            }
        )
    rows = []
    required = set(_TDIUC_CATEGORY.values())
    for image_id, categories in grouped.items():
        if set(categories) != required:
            continue
        selected = []
        for category in sorted(required):
            selected.append(
                min(categories[category], key=lambda item: _rank(item["source_question_id"]))
            )
        source_id = str(image_id)
        rows.append(
            ImageCandidate(
                f"tdiuc-{source_id}",
                source_id,
                "TDIUC-val/MS-COCO-val2014",
                f"http://images.cocodataset.org/val2014/COCO_val2014_{image_id:012d}.jpg",
                tuple(selected),
            )
        )
    return sorted(rows, key=lambda item: _rank(item.image_id))


def _textvqa_candidates(path: Path) -> list[ImageCandidate]:
    grouped: dict[str, list[dict]] = defaultdict(list)
    metadata = {}
    for item in json.loads(path.read_text(encoding="utf-8"))["data"]:
        grouped[item["image_id"]].append(
            {
                "source_question_id": str(item["question_id"]),
                "text": item["question"].strip(),
                "category": "OCR",
                "accepted_answers": _answers(item),
                "source_question_type": "textvqa",
            }
        )
        metadata[item["image_id"]] = item
    rows = []
    for image_id, questions in grouped.items():
        if len(questions) != 2:
            continue
        item = metadata[image_id]
        rows.append(
            ImageCandidate(
                f"textvqa-{image_id}",
                image_id,
                "TextVQA-0.5.1-val/OpenImages",
                item["flickr_300k_url"],
                tuple(sorted(questions, key=lambda row: row["source_question_id"])),
            )
        )
    return sorted(rows, key=lambda item: _rank(item.image_id))


def _fetch_candidate(
    candidate: ImageCandidate, image_root: Path
) -> tuple[ImageCandidate, dict] | None:
    suffix = Path(candidate.url.split("?", 1)[0]).suffix.lower()
    suffix = suffix if suffix in {".jpg", ".jpeg", ".png", ".webp"} else ".jpg"
    path = image_root / f"{candidate.image_id}{suffix}"
    try:
        _download(candidate.url, path)
        with Image.open(path) as image:
            image.verify()
        with Image.open(path) as image:
            width, height = image.size
            image_format = image.format
    except Exception:
        path.unlink(missing_ok=True)
        return None
    payload = path.read_bytes()
    return candidate, {
        "image_id": candidate.image_id,
        "source_id": candidate.source_id,
        "source": candidate.source,
        "source_url": candidate.url,
        "local_path": str(path.resolve()),
        "sha256": sha256_bytes(payload),
        "size_bytes": len(payload),
        "width": width,
        "height": height,
        "format": image_format,
    }


def _download_selection(
    candidates: list[ImageCandidate], count: int, image_root: Path
) -> tuple[list[ImageCandidate], list[dict]]:
    selected = []
    records = []
    cursor = 0
    while len(selected) < count:
        batch = candidates[cursor : cursor + max(16, count - len(selected))]
        if not batch:
            raise RuntimeError(f"only {len(selected)} of {count} images could be downloaded")
        cursor += len(batch)
        with ThreadPoolExecutor(max_workers=8) as executor:
            futures = [executor.submit(_fetch_candidate, item, image_root) for item in batch]
            results = [future.result() for future in as_completed(futures)]
        ordered = sorted(
            (item for item in results if item is not None), key=lambda pair: _rank(pair[0].image_id)
        )
        for candidate, record in ordered:
            if len(selected) >= count:
                break
            selected.append(candidate)
            records.append(record)
    return selected, records


def prepare_dataset(cache_root: Path, artifact_root: Path) -> dict:
    tdiuc_root, textvqa_path = _prepare_sources(cache_root)
    image_root = cache_root / "images"
    tdiuc, tdiuc_images = _download_selection(
        _tdiuc_candidates(tdiuc_root), TDIUC_IMAGE_COUNT, image_root
    )
    textvqa, textvqa_images = _download_selection(
        _textvqa_candidates(textvqa_path), TEXTVQA_IMAGE_COUNT, image_root
    )
    images = tdiuc_images + textvqa_images
    selected = tdiuc + textvqa
    questions = []
    truth = []
    for candidate in selected:
        for index, item in enumerate(candidate.questions, start=1):
            question_id = f"{candidate.image_id}-q{index}"
            questions.append(
                {
                    "benchmark_version": BENCHMARK_VERSION,
                    "question_id": question_id,
                    "image_id": candidate.image_id,
                    "category": item["category"],
                    "question": item["text"],
                    "source": candidate.source,
                    "source_question_id": item["source_question_id"],
                    "source_question_type": item["source_question_type"],
                }
            )
            truth.append(
                {
                    "benchmark_version": BENCHMARK_VERSION,
                    "question_id": question_id,
                    "image_id": candidate.image_id,
                    "category": item["category"],
                    "accepted_answers": item["accepted_answers"],
                    "primary_answer": item["accepted_answers"][0],
                    "normalization": "ocr-conservative"
                    if item["category"] == "OCR"
                    else "objective-v1",
                }
            )
    category_counts = Counter(item["category"] for item in questions)
    manifest = {
        "benchmark_version": BENCHMARK_VERSION,
        "selection_seed": SELECTION_SEED,
        "images": images,
        "image_count": len(images),
        "question_count": len(questions),
        "category_counts": dict(sorted(category_counts.items())),
        "sources": [
            {
                "name": "TDIUC validation",
                "url": TDIUC_URL,
                "sha256": TDIUC_SHA256,
                "role": "independent question and ground-truth annotations for six categories",
            },
            {
                "name": "TextVQA 0.5.1 validation",
                "url": TEXTVQA_URL,
                "sha256": TEXTVQA_SHA256,
                "role": "independent OCR question and human-answer annotations",
            },
        ],
        "selection_policy": "80 TDIUC COCO images with all six mapped categories and one deterministic question per category; 20 TextVQA images with two validation questions",
        "ground_truth_policy": "dataset annotations only; TextVQA accepts answers with at least three annotator votes, falling back to the modal answer",
        "image_storage": str(image_root.resolve()),
    }
    write_json(artifact_root / "dataset-manifest.json", manifest)
    write_jsonl(artifact_root / "questions.jsonl", questions)
    write_jsonl(artifact_root / "ground-truth.jsonl", truth)
    return manifest
